const sheet=document.querySelector('#sheet'),shade=document.querySelector('#shade'),sheetRoom=document.querySelector('#sheetRoom');function openSheet(room='Room 3'){sheetRoom.textContent=room;sheet.classList.add('open');shade.classList.add('on')}function closeSheet(){sheet.classList.remove('open');shade.classList.remove('on')}document.querySelectorAll('[data-room]').forEach(b=>b.addEventListener('click',()=>openSheet(b.dataset.room)));document.querySelector('#bookNav').addEventListener('click',()=>openSheet('Room 3'));document.querySelector('#nextOpening').addEventListener('click',()=>openSheet('Room 5'));document.querySelector('#close').addEventListener('click',closeSheet);shade.addEventListener('click',closeSheet);document.querySelectorAll('.end-times button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.end-times button').forEach(x=>x.classList.remove('active'));b.classList.add('active')}));document.addEventListener('keydown',e=>{if(e.key==='Escape')closeSheet()});